def select_neighbor(archive: List[Tuple[np.ndarray, Tuple[float, float]]], weight_lst: np.ndarray, value1_lst: np.ndarray, value2_lst: np.ndarray, capacity: float) -> np.ndarray:
    """
    Select a promising solution from the archive and generate a neighbor solution from it.

    Args:
    archive: List of (solution, objective) pairs. Each solution is a binary numpy array (0/1) of item selections.
             Each objective is a tuple of two float values (total value1, total value2).
    weight_lst: Numpy array of shape (N, ), item weights.
    value1_lst: Numpy array of shape (N, ), item values for objective 1.
    value2_lst: Numpy array of shape (N, ), item values for objective 2.
    capacity: Maximum allowed total weight.

    Returns:
    A new neighbor solution (numpy array).
    """
    if not archive:
        raise ValueError("Archive is empty")

    # Step 1: Select a solution based on hybrid of crowding distance and dominance rank
    def calculate_dominance_rank(solutions):
        ranks = np.zeros(len(solutions))
        for i in range(len(solutions)):
            for j in range(len(solutions)):
                if i != j:
                    if solutions[i][1][0] >= solutions[j][1][0] and solutions[i][1][1] >= solutions[j][1][1]:
                        if solutions[i][1][0] > solutions[j][1][0] or solutions[i][1][1] > solutions[j][1][1]:
                            ranks[i] += 1
        return ranks

    def calculate_crowding_distance(solutions):
        distances = np.zeros(len(solutions))
        for m in range(2):
            sorted_idx = np.argsort([sol[1][m] for sol in solutions])
            distances[sorted_idx[0]] = distances[sorted_idx[-1]] = float('inf')
            for i in range(1, len(solutions)-1):
                if solutions[sorted_idx[-1]][1][m] != solutions[sorted_idx[0]][1][m]:
                    distances[sorted_idx[i]] += (solutions[sorted_idx[i+1]][1][m] - solutions[sorted_idx[i-1]][1][m]) / (solutions[sorted_idx[-1]][1][m] - solutions[sorted_idx[0]][1][m])
        return distances

    ranks = calculate_dominance_rank(archive)
    distances = calculate_crowding_distance(archive)
    combined_scores = ranks + distances
    selected_idx = np.argmax(combined_scores)
    base_solution = archive[selected_idx][0].copy()
    current_weight = np.sum(weight_lst * base_solution)

    # Step 2: Apply multi-phase local search
    new_solution = base_solution.copy()
    n_items = len(base_solution)

    # Phase 1: Adaptive value-weight ratio swaps
    in_sol = np.where(new_solution == 1)[0]
    out_sol = np.where(new_solution == 0)[0]
    if len(in_sol) > 0 and len(out_sol) > 0:
        alpha = 0.7
        combined_values = alpha * value1_lst + (1 - alpha) * value2_lst
        value_ratios = combined_values / weight_lst
        best_in = in_sol[np.argmin(value_ratios[in_sol])]
        best_out = out_sol[np.argmax(value_ratios[out_sol])]
        if current_weight - weight_lst[best_in] + weight_lst[best_out] <= capacity:
            new_solution[best_in], new_solution[best_out] = new_solution[best_out], new_solution[best_in]
            current_weight = current_weight - weight_lst[best_in] + weight_lst[best_out]

    # Phase 2: Dominance-aware flips
    flip_candidates = np.argsort((value1_lst + value2_lst) / (weight_lst + 1e-6))[::-1]
    for idx in flip_candidates[:min(5, len(flip_candidates))]:
        if new_solution[idx] == 1:
            if current_weight - weight_lst[idx] <= capacity:
                new_solution[idx] = 0
                current_weight -= weight_lst[idx]
        else:
            if current_weight + weight_lst[idx] <= capacity:
                new_solution[idx] = 1
                current_weight += weight_lst[idx]

    # Phase 3: Capacity-constrained perturbations
    perturb_size = min(3, n_items // 3)
    perturb_indices = np.random.choice(n_items, size=perturb_size, replace=False)
    for idx in perturb_indices:
        if new_solution[idx] == 1:
            if current_weight - weight_lst[idx] <= capacity:
                new_solution[idx] = 0
                current_weight -= weight_lst[idx]
        else:
            if current_weight + weight_lst[idx] <= capacity and (value1_lst[idx] > 0 or value2_lst[idx] > 0):
                new_solution[idx] = 1
                current_weight += weight_lst[idx]

    return new_solution
